目录常见思路更优的解法（面试官喜欢的）常见思路要选出最小的前K个数首先我们会想到排排升序建大堆，排降序建小堆一个直观的想法是使用（小根堆），起始将所有元素放入堆中，然后再从堆中
 取出k 个元素并「顺序」构造答案。你写出了用小堆解决的代码void swap(int* a, int* b) {
    int t = *a;
    *a = *b;
    *b = t;
}


void minHeapify(int arr[], int n, int i) {
    int smallest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2; 


    if (left < n && arr[left] < arr[smallest])
        smallest = left;


    if (right < n && arr[right] < arr[smallest])
        smallest = right;


    if (smallest != i) {
        swap(&arr[i], &arr[smallest]);

        minHeapify(arr, n, smallest);
    }
}


void buildMinHeap(int arr[], int n) {
    // Index of last non-leaf node
    int startIdx = (n / 2) - 1;

    for (int i = startIdx; i >= 0; i--)
        minHeapify(arr, n, i);
}


int extractMin(int arr[], int* n) {
    if (*n <= 0)
        return INT_MAX;
    if (*n == 1) {
        (*n)--;
        return arr[0];
    }


    int root = arr[0];
    arr[0] = arr[*n - 1];
    (*n)--;
    minHeapify(arr, *n, 0);

    return root;
}

void findKSmallest(int arr[], int n, int k) {

    buildMinHeap(arr, n);

    printf("The k smallest elements are: ");
    for (int i = 0; i < k; i++) {
        printf("%d ", extractMin(arr, &n));
    }
    printf("\n");
}分析一下不难发现建堆的复杂度是O（N）每次提取的复杂度是O(logN)总的复杂度O（NlogN）面试官看到你的代码后，并不满意并要求你进行优化更优的解法（面试官喜欢的）使用（大根堆）!当处理到原始 arr[i] 时，根据堆内元素个数，以及其与堆顶元素的关系分情况讨论：堆内元素不足 k 个：直接将 arr[i] 放入堆内；堆内元素为 k 个：根据 arr[i] 与堆顶元素的大小关系分情况讨论：arr[i]>=heapTop：arr[i] 不可能属于第 k 小数（已有 k 个元素在堆中），直接丢弃 arr[i]；arr[i]<heapTop：arr[i] 可能属于第 k 小数，弹出堆顶元素，并放入 arr[i]。你出写了如下代码。void swap(int* a, int* b) {
    int t = *a;
    *a = *b;
    *b = t;
}


void maxHeapify(int arr[], int n, int i) {
    int largest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2; 

    // 如果左子节点大于当前节点，则更新最大值索引
    if (left < n && arr[left] > arr[largest])
        largest = left;

    // 如果右子节点大于当前节点，则更新最大值索引
    if (right < n && arr[right] > arr[largest])
        largest = right;

    // 如果最大值索引不是当前节点，则交换并递归调整子树
    if (largest != i) {
        swap(&arr[i], &arr[largest]);
        maxHeapify(arr, n, largest);
    }
}


void buildMaxHeap(int arr[], int n) {
    // 最后一个非叶子节点的索引
    int startIdx = (n / 2) - 1;

    // 从最后一个非叶子节点开始，逆序遍历并调整每个节点
    for (int i = startIdx; i >= 0; i--)
        maxHeapify(arr, n, i);
}

// 提取堆顶元素并调整堆的函数
int extractMax(int arr[], int* n) {
    if (*n <= 0)
        return INT_MAX; // 堆为空时返回最大整数值
    if (*n == 1) {
        (*n)--;
        return arr[0]; // 堆只有一个元素时直接返回
    }

    // 存储并移除堆顶元素
    int root = arr[0];
    arr[0] = arr[*n - 1];
    (*n)--;
    maxHeapify(arr, *n, 0); // 调整堆以保持大根堆性质

    return root;
}


void findKSmallest(int arr[], int n, int k) {
    // 构建包含前k个元素的大根堆
    int heap[k];
    for (int i = 0; i < k; i++) {
        heap[i] = arr[i];
    }
    buildMaxHeap(heap, k);

    // 遍历剩余元素
    for (int i = k; i < n; i++) {
        // 如果当前元素小于堆顶元素，则替换堆顶元素并重新调整堆
        if (arr[i] < heap[0]) {
            heap[0] = arr[i];
            maxHeapify(heap, k, 0);
        }
    }
}时间复杂度O（NlogK），当N无限大时logK可以忽略比O（NlogN）更优

Node.js 是一个基于事件驱动、非阻塞 I/O 模型的 JavaScript 运行时环境，特别适合构建高并发的网络应用。然而，由于其单线程架构，在处理 CPU 密集型任务时可能会遇到瓶颈。本文将介绍几种解决 Node.js 单线程限制的方法，帮助你提高应用程序的性能和可扩展性。1. 使用集群（Cluster）Node.js 提供了cluster模块，可以创建多个工作进程来共享同一个服务器端口，从而充分利用多核 CPU。以下是一个简单的示例：constcluster=require('cluster');consthttp=require('http');constnumCPUs=require('os').cpus().length;if(cluster.isMaster){// 创建工作进程for(leti=0;i<numCPUs;i++){cluster.fork();}cluster.on('exit',(worker,code,signal)=>{console.log(`工作进程${worker.process.pid}已退出`);});}else{// 工作进程可以共享同一个服务器端口http.createServer((req,res)=>{res.writeHead(200);res.end('你好，世界\n');}).listen(8000);}在这个示例中，主进程（Master）会创建与 CPU 核心数量相同的工作进程（Worker），每个工作进程都可以处理请求，从而提高应用程序的并发处理能力。2. 使用子进程（Child Processes）对于 CPU 密集型任务，可以使用child_process模块创建子进程来处理这些任务，从而避免阻塞主线程。以下是一个示例：const{fork}=require('child_process');constcompute=fork('compute.js');compute.on('message',(result)=>{console.log(`计算结果:${result}`);});compute.send('开始计算');在compute.js文件中：process.on('message',(msg)=>{if(msg==='开始计算'){// 执行 CPU 密集型任务letresult=0;for(leti=0;i<1e9;i++){result+=i;}process.send(result);}});通过这种方式，主进程可以将 CPU 密集型任务交给子进程处理，从而避免阻塞事件循环。3. 使用 Web WorkersNode.js 12 及以上版本支持 Web Workers，可以在独立的线程中运行 JavaScript 代码。以下是一个示例：const{Worker}=require('worker_threads');constworker=newWorker(`const { parentPort } = require('worker_threads');
  let result = 0;
  for (let i = 0; i < 1e9; i++) {
    result += i;
  }
  parentPort.postMessage(result);`,{eval:true});worker.on('message',(result)=>{console.log(`计算结果:${result}`);});Web Workers 提供了一种在独立线程中运行 JavaScript 代码的方式，可以有效地处理 CPU 密集型任务。4. 使用异步 I/O 操作尽量使用异步 I/O 操作来避免阻塞事件循环。Node.js 提供了许多异步 API，可以有效地处理 I/O 密集型任务。例如，使用fs模块的异步方法读取文件：constfs=require('fs');fs.readFile('example.txt','utf8',(err,data)=>{if(err){console.error('无法读取文件:',err);return;}console.log('文件内容:',data);});通过使用异步方法，可以在文件读取过程中继续处理其他请求，从而提高应用程序的并发处理能力。5. 使用负载均衡在高并发场景下，可以使用负载均衡器（如 Nginx）将请求分发到多个 Node.js 实例，从而提高应用程序的吞吐量和可靠性。以下是一个简单的 Nginx 配置示例：http {
  upstream nodejs_backend {
    server 127.0.0.1:3000;
    server 127.0.0.1:3001;
    server 127.0.0.1:3002;
    server 127.0.0.1:3003;
  }

  server {
    listen 80;

    location / {
      proxy_pass http://nodejs_backend;
      proxy_set_header Host $host;
      proxy_set_header X-Real-IP $remote_addr;
      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
    }
  }
}通过这种方式，Nginx 可以将请求分发到多个 Node.js 实例，从而提高应用程序的并发处理能力。结论通过使用集群、子进程、Web Workers、异步 I/O 操作和负载均衡等方法，可以有效地解决 Node.js 的单线程限制，提高应用程序的性能和可扩展性。

